import {createDemoRepository} from './repository.mjs';
import {createFirebaseRepository} from './firebase-repository.mjs';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('he-IL',{style:'currency',currency:'ILS',maximumFractionDigits:Number(n)%100?2:0}).format((Number(n)||0)/100);
const date=v=>v?new Date(v).toLocaleString('he-IL',{dateStyle:'short',timeStyle:'short',timeZone:'Asia/Jerusalem'}):'';
const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now()+'-'+Math.random().toString(36).slice(2);
const logo=`<span class="logo"><img src="assets/brand/madaf-logo.png" width="720" height="252" alt="מדף"></span>`;
const statuses={pending_approval:'ממתינה לאישור',received:'התקבלה',picking:'בליקוט',completed:'הושלמה',cancelled:'בוטלה',rejected:'נדחתה'};
// 'hosting': read the public web config Firebase Hosting serves at /__/firebase/init.json, and keep the auth
// handler on this same origin (the custom domain) so sign-in does not depend on third-party storage.
async function resolveFirebaseConfig(config){if(config!=='hosting')return config;const r=await fetch('/__/firebase/init.json');if(!r.ok)throw Error('טעינת הגדרות Firebase נכשלה');return {...await r.json(),authDomain:location.host};}
// Admins can switch between the management side and their own customer side. The switch only changes the view:
// the server always authorizes by the real role and by business ownership.
const MODE_KEY='madaf-mode';let mode='admin';try{mode=localStorage.getItem(MODE_KEY)==='customer'?'customer':'admin'}catch{}
function viewActor(){const a=repo?.actor;return a&&a.role==='admin'&&mode==='customer'?{...a,role:'customer'}:a}
function modeSwitch(){return repo.actor?.role==='admin'?`<button class="secondary mode-switch" data-action="mode" aria-label="${mode==='admin'?'מעבר למצב לקוח':'מעבר למצב ניהול'}">${mode==='admin'?'מצב לקוח':'מצב ניהול'}</button>`:''}
let repo;try{repo=window.MADAF_FIREBASE_CONFIG?await createFirebaseRepository(await resolveFirebaseConfig(window.MADAF_FIREBASE_CONFIG)):await createDemoRepository()}catch(e){document.getElementById('app').innerHTML='<main class="page"><h1>לא ניתן לפתוח את מדף</h1><p>'+esc(e.message)+'</p><button class="primary" onclick="location.reload()">ניסיון חוזר</button><p>הנתונים לא אופסו.</p></main>';throw e;}
let db=repo.snapshot(),actor=viewActor(),view='catalog',category='all',query='',filter='all',selected=null,cart={},note='',expanded=false,busy=false,dialog=null,returnFocus=null,draftConflict=null,undo=null;
const app=$('#app'),overlays=$('#overlays');
const biz=()=>db.businesses.find(b=>b.id===actor?.businessId);
const productCache=new Map();
const product=id=>db.products.find(p=>p.id===id)|| (productCache.has(id)?{...productCache.get(id),active:false,stock:0}:null);
const openRequest=o=>o.request&&['pending','stock_conflict'].includes(o.request.status);
const normalize=s=>String(s).toLowerCase().replace(/[\s־–-]/g,'');
const draftKey=()=>`madaf-draft-${actor?.id}-${actor?.businessId}`;
function loadDraft(){try{const d=JSON.parse(localStorage.getItem(draftKey())||'null');cart=d?.cart||{};note=d?.note||'';pendingSubmit=d?.pendingSubmit||null;(d?.products||[]).forEach(p=>productCache.set(p.id,p));if(d&&Object.keys(cart).length)setTimeout(()=>toast('הטיוטה שלך שוחזרה · '+date(d.savedAt)),100)}catch{cart={};note=''}}
function saveDraft(){try{localStorage.setItem(draftKey(),JSON.stringify({cart,note,pendingSubmit,products:cartItems().map(x=>x.p),savedAt:new Date().toISOString()}))}catch{toast('לא ניתן לשמור טיוטה במכשיר. השאירו את החלון פתוח.')}}
function toast(message,action){const t=$('#toast');t.innerHTML=`<span>${esc(message)}</span>${action?`<button id="toast-action">${esc(action.label)}</button>`:''}`;t.classList.add('show');if(action)$('#toast-action').onclick=()=>{action.run();t.classList.remove('show')};clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),action?12000:5500)}
function ctx(){return{top:scrollY,details:$$('[data-details]').map(e=>[e.dataset.details,e.open]),scroll:$$('[data-scroll]').map(e=>[e.dataset.scroll,e.scrollLeft,e.scrollTop]),focus:document.activeElement?.id,selection:document.activeElement?.selectionStart}}
function restore(c){for(const[id,open]of c.details||[]){const d=$(`[data-details="${id}"]`);if(d)d.open=open}if(c.top!==undefined)scrollTo(0,c.top);for(const [id,x,y]of c.scroll){const e=$(`[data-scroll="${id}"]`);if(e){e.scrollLeft=x;e.scrollTop=y}}if(c.focus){const e=document.getElementById(c.focus);e?.focus({preventScroll:true});try{e?.setSelectionRange(c.selection,c.selection)}catch{}}}
function tag(o){return `<span class="tag">${esc(statuses[o.status]||o.status)}</span>`}
function art(p){const icons=['◒','▥','◡','▧','◕'];return p.image?`<img src="${esc(p.image)}" alt="${esc(p.name)}" loading="lazy" onerror="this.style.display='none';this.nextElementSibling.hidden=false"><span class="fallback" hidden>▧</span>`:`<span class="fallback" aria-hidden="true">${icons[Math.abs([...p.id].reduce((n,c)=>n+c.charCodeAt(0),0))%icons.length]}</span>`}
function quantity(p,q=cart[p.id]||0,prefix='cart'){return `<div class="qty"><button data-action="qty" data-id="${esc(p.id)}" data-delta="1" data-prefix="${prefix}" aria-label="הוסף ארגז ${esc(p.name)}">+</button><input id="${prefix}-qty-${esc(p.id)}" data-quantity="${esc(p.id)}" data-prefix="${prefix}" type="number" inputmode="numeric" min="0" step="1" value="${q}" aria-label="ארגזים של ${esc(p.name)}"><button data-action="qty" data-id="${esc(p.id)}" data-delta="-1" data-prefix="${prefix}" aria-label="הפחת ארגז ${esc(p.name)}">−</button></div>`}
function tile(p,shelfId='main'){const q=cart[p.id]||0;return `<article class="product ${q?'selected':''}" data-product="${esc(p.id)}"><button class="product-open" data-action="quick" data-id="${esc(p.id)}" id="open-${esc(shelfId)}-${esc(p.id)}"><div class="product-art">${art(p)}<span class="selected-label ${q?'':'hidden'}">בהזמנה שלך</span></div><div class="product-copy"><h3>${esc(p.name)}</h3><small>${esc(p.sku)} · ${p.unitsPerCase} יח׳ בארגז</small></div></button><div class="product-bottom"><div class="row spread"><span class="price">${money(p.price)}</span>${quantity(p,q,'card-'+shelfId)}</div><div class="stock ${p.stock<=3?'low':''}">${p.stock<=3?`נותרו רק ${p.stock} ארגזים`:'זמין להזמנה'} · לפני מע״מ</div><small class="units">${q?`${q} ארגזים · ${q*p.unitsPerCase} יחידות`:'ארגזים שלמים, לבחירתך'}</small></div></article>`}
function header(){return `<header class="topbar"><button class="icon-btn" id="nav-toggle" data-action="drawer" data-side="nav" aria-label="פתח ניווט" aria-expanded="false" aria-controls="navigation-drawer">☰</button><div class="brand">${logo}</div><div class="business"><strong>${esc(biz()?.name||'שולחן התפעול')}</strong><div class="status muted">${actor.role==='admin'?'כל מה שדורש תשומת לב':biz()?.approved?'העסק שלך, ההזמנות שלך':'הזמנה ראשונה באישור הצוות'}</div></div><span class="demo">${repo.mode==='demo'?'סביבת הדגמה':''}</span>${modeSwitch()}<button class="icon-btn" id="tools-toggle" data-action="drawer" data-side="tools" aria-label="פתח כלים" aria-expanded="false" aria-controls="tools-drawer">⌘</button>${actor.role!=='admin'?`<input class="search" id="search" type="search" value="${esc(query)}" placeholder="חיפוש שם מוצר או מק״ט" aria-label="חיפוש מוצרים">`:''}</header>${!navigator.onLine?'<div class="top-notice">אין חיבור — הטיוטה נשמרת במכשיר. שליחה מחייבת חיבור.</div>':''}${draftConflict?'<div class="top-notice">הטיוטה עודכנה בלשונית אחרת. <button data-action="load-draft" class="text-btn">טען את העדכון</button></div>':''}`}
function welcome(){return `<main class="welcome"><section class="welcome-copy"><img class="brand-logo" src="assets/brand/madaf-logo.png" width="720" height="252" alt="מדף"><div class="eyebrow" style="margin-top:20px">הזמנות לעסקים</div><h1>מקום לכל מוצר.<br>שקט לכל הזמנה.</h1><p>המדף שלכם, פתוח תמיד.<br>בוחרים ארגזים, מרכיבים הזמנה וממשיכים ביום.</p><div class="login-options">${repo.mode==='demo'?`<label>עסק להדגמה<select id="demo-business">${db.businesses.map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}</select></label><button class="primary" data-action="login" data-persona="customer">כניסה לחנות הדגמה ←</button><div class="row"><button class="secondary" data-action="login" data-persona="new">עסק חדש</button><button class="text-btn" data-action="login" data-persona="admin">שולחן התפעול</button></div><small>הדגמה מקומית · נתונים לדוגמה · ללא שליחת הודעות</small>`:`<button class="primary google-login" data-action="login" data-persona="customer"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path fill="#fff" d="M21.35 11.1H12v2.97h5.35c-.23 1.4-1.66 4.1-5.35 4.1-3.22 0-5.85-2.67-5.85-5.96S8.78 6.25 12 6.25c1.83 0 3.06.78 3.76 1.45l2.56-2.47C16.68 3.7 14.55 2.75 12 2.75 6.9 2.75 2.75 6.9 2.75 12S6.9 21.25 12 21.25c5.34 0 8.88-3.75 8.88-9.04 0-.6-.07-1.06-.15-1.51z"/></svg>כניסה עם Google</button><small>בכניסה הראשונה ממלאים פרטי עסק. ההזמנה הראשונה עוברת לאישור הצוות.</small>`}</div></section><section class="welcome-art" aria-hidden="true"><div class="display-shelf"><span></span><span></span><span></span></div><div class="caption">נבחרים בקפידה. מוזמנים בפשטות.</div></section></main>`}
function catalog(){let list=db.products.filter(p=>p.active&&p.stock>0);const cats=db.categories.filter(c=>c.active).sort((a,b)=>a.sortOrder-b.sortOrder);list=list.filter(p=>cats.some(c=>c.id===p.categoryId));const found=list.filter(p=>normalize(p.name+' '+p.sku).includes(normalize(query)));const visible=found.filter(p=>category==='all'||p.categoryId===category);const orders=db.orders.filter(o=>o.businessId===actor.businessId&&!['cancelled','rejected'].includes(o.status)).sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt))).slice(0,2);const recent=orders.length===2?visible.filter(p=>orders.every(o=>o.items.some(i=>i.productId===p.id))):[];const shelf=(name,items,id)=>`<section class="shelf"><div class="shelf-head"><h2>${esc(name)}</h2><small>${items.length} מוצרים</small><button class="icon-btn rail-button" data-action="rail" data-id="${id}" data-dir="prev" aria-label="חזרה במדף">→</button><button class="icon-btn rail-button" data-action="rail" data-id="${id}" data-dir="next" aria-label="המשך במדף">←</button></div><div class="rail" data-scroll="${id}">${items.map(p=>tile(p,id)).join('')}</div></section>`;return `<div class="catalog"><div class="intro"><div><div class="eyebrow">המדף שלכם</div><h1>מה נכנס להזמנה היום?</h1><p>בוחרים ארגזים. ההזמנה נשארת בהישג יד.</p></div><button class="text-btn" data-action="view" data-view="orders">ההזמנות שלי ←</button></div><div class="chips" data-scroll="categories"><button class="chip ${category==='all'?'active':''}" data-action="category" data-id="all">כל המדפים</button>${cats.map(c=>`<button class="chip ${category===c.id?'active':''}" data-action="category" data-id="${esc(c.id)}">${esc(c.name)}</button>`).join('')}</div>${query||category!=='all'?`<div class="row spread" style="margin-bottom:20px"><small>${visible.length} מוצרים ${query?`עבור “${esc(query)}”`:''}</small><button class="text-btn" data-action="clear-search">נקה חיפוש וסינון</button></div>`:''}${recent.length&&!query&&category==='all'?shelf('שוב על המדף שלכם',recent,'recent'):''}${visible.length?cats.filter(c=>visible.some(p=>p.categoryId===c.id)).map(c=>shelf(c.name,visible.filter(p=>p.categoryId===c.id),c.id)).join(''):`<div class="empty"><h2>לא נמצאו מוצרים</h2><p>אפשר לנסות שם קצר יותר או מק״ט.</p>${found.length?`<button class="primary" data-action="category" data-id="all">הצג ${found.length} מוצרים בקטגוריות אחרות</button>`:'<button class="secondary" data-action="clear-search">חזרה לכל המדפים</button>'}</div>`}</div>`}
const cartItems=()=>Object.entries(cart).filter(([,q])=>q>0).map(([id,q])=>({p:product(id),q})).filter(x=>x.p);
const available=(p,q)=>p.active&&p.stock>=q&&db.categories.some(c=>c.id===p.categoryId&&c.active);
const subtotal=()=>cartItems().reduce((n,{p,q})=>n+p.price*q,0);
function totals(sum,rate=db.settings.vatRate){const vat=Math.round(sum*rate);return `<div class="totals"><div><span>סכום לפני מע״מ</span><strong>${money(sum)}</strong></div><div><span>מע״מ ${Math.round(rate*100)}%</span><span>${money(vat)}</span></div><div class="grand"><span>סה״כ</span><strong>${money(sum+vat)}</strong></div></div>`}
function cartContent(){return `<button class="text-btn" data-action="clear-cart">מחיקת טיוטה</button><div class="notice">טיוטת הזמנה · ${esc(biz()?.name)}<br><small>מחירים ומלאי יאומתו לפני השליחה.</small></div>${cartItems().map(({p,q})=>`<div class="cartline ${!available(p,q)?'unavailable':''}"><div><h3>${esc(p.name)}</h3><small>${q} ארגזים · ${q*p.unitsPerCase} יחידות</small>${!available(p,q)?'<p class="field-error">המוצר או הכמות אינם זמינים כעת</p>':''}<button class="text-btn" data-action="remove" data-id="${p.id}">הסרה</button></div><div>${quantity(p,q,'living')}<div style="text-align:left;margin-top:7px">${money(p.price*q)}</div></div></div>`).join('')}<div style="margin-top:16px"><label>הערה להזמנה<textarea id="cart-note" placeholder="משהו שחשוב שנדע?">${esc(note)}</textarea></label></div>${totals(subtotal())}${cartItems().some(({p,q})=>!available(p,q))?`<p class="field-error">סכום הפריטים הזמינים: ${money(cartItems().filter(({p,q})=>available(p,q)).reduce((n,{p,q})=>n+p.price*q,0))}. יש להסיר או לעדכן פריטים שאינם זמינים.</p>`:''}<button class="primary" style="width:100%" data-action="checkout" ${subtotal()<db.settings.minimumOrder||cartItems().some(({p,q})=>!available(p,q))?'disabled':''}>המשך לאישור ←</button>`}
function living(){const count=cartItems().reduce((n,x)=>n+x.q,0);return `<aside class="living ${expanded?'expanded':''} ${!count?'hidden':''}" aria-label="טיוטת הזמנה"><button class="living-handle" id="living-toggle" data-action="expand" aria-expanded="${expanded}"><span class="grab"></span><span class="row spread"><span><strong class="living-title">${count} ארגזים · ${money(subtotal())}</strong><br><small>${subtotal()<db.settings.minimumOrder?`עוד ${money(db.settings.minimumOrder-subtotal())} למינימום לפני מע״מ`:'הגעת למינימום · לפני מע״מ'}</small></span><span>${expanded?'⌄':'לצפייה בהזמנה ↑'}</span></span></button><div class="living-content" data-scroll="living">${expanded?cartContent():''}</div></aside>`}
function ownOrders(){return db.orders.filter(o=>actor.role==='admin'||o.businessId===actor.businessId).sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)))}
function orderList(){const os=ownOrders();return `<div class="intro"><div><div class="eyebrow">היסטוריית העסק</div><h1>ההזמנות שלי</h1><p>כל הזמנה, מהשליחה ועד ההשלמה.</p></div><button class="text-btn" data-action="view" data-view="catalog">חזרה למדף ←</button></div><div class="queue">${os.length?os.map(o=>orderButton(o)).join(''):'<div class="empty"><h2>ההזמנה הראשונה מתחילה במדף</h2><button class="primary" data-action="view" data-view="catalog">לבחירת מוצרים</button></div>'}</div>`}
function orderButton(o){return `<button class="queue-item ${selected===o.id?'active':''}" data-action="order" data-id="${o.id}"><div class="row spread"><span>#${esc(o.number)}</span>${tag(o)}</div><h3>${esc(o.businessSnapshot?.name||db.businesses.find(b=>b.id===o.businessId)?.name||'הזמנה')}</h3><div class="row spread"><small>${date(o.createdAt)}</small><strong>${money(o.total)}</strong></div>${openRequest(o)?`<div class="stock low">${o.request.type==='change'?'בקשת שינוי':'בקשת ביטול'} · ${o.request.status==='stock_conflict'?'חוסר במלאי':`ממתינה ${waitLabel(o.request.createdAt)}`}</div>`:''}</button>`}
function lines(items){return `<table class="order-lines"><thead><tr><th>מוצר</th><th>ארגזים</th><th>לארגז</th><th>סכום</th></tr></thead><tbody>${items.map(i=>`<tr><td>${esc(i.name||product(i.productId)?.name)}<br><small>${esc(i.sku||'')} · ${i.unitsPerCase||product(i.productId)?.unitsPerCase} יח׳</small></td><td>${i.quantity}</td><td>${money(i.price)}</td><td>${money(i.price*i.quantity)}</td></tr>`).join('')}</tbody></table>`}
function diff(o){const items=o.request.items||[];const ids=[...new Set([...o.items,...items].map(i=>i.productId))];return `<table class="order-lines"><thead><tr><th>מוצר</th><th>מקור</th><th>מוצע</th><th>שינוי</th></tr></thead><tbody>${ids.map(id=>{let a=o.items.find(i=>i.productId===id),b=items.find(i=>i.productId===id);return `<tr class="${(a?.quantity||0)!==(b?.quantity||0)?'changed-row':''}"><td>${esc((b||a).name||product(id)?.name)}<br><small>${b&&(b.quantity>(a?.quantity||0))?`נדרשים ${b.quantity-(a?.quantity||0)} נוספים · זמינים ${product(id)?.stock||0}`:''}</small></td><td>${a?.quantity||0}</td><td>${b?.quantity||0}</td><td>${money((b?.quantity||0)*(b?.price||0)-(a?.quantity||0)*(a?.price||0))}</td></tr>`}).join('')}</tbody></table>`}
function orderDetail(o){const admin=actor.role==='admin';return `<button class="text-btn mobile-back" data-action="back-list">חזרה לרשימה →</button><div class="row spread"><div><div class="eyebrow">${esc(o.businessSnapshot?.name||'פרטי הזמנה')}</div><h2>הזמנה #${esc(o.number)}</h2></div>${tag(o)}</div><div class="row spread"><small>${date(o.createdAt)}</small><button class="text-btn" data-action="copy" data-value="${esc(o.number)}">העתק מספר</button>${admin?`<button class="text-btn" data-action="copy-link" data-id="${o.id}">העתק קישור</button>`:''}</div><div class="notice" style="margin-top:15px">${esc(o.businessSnapshot?.address||'')}<br><small>${esc(o.businessSnapshot?.contactName||'')} · ${esc(o.businessSnapshot?.phone||'')}</small></div>${lines(o.items)}${totals(o.subtotal,o.vatRate)}${o.note?`<p class="notice">הערת לקוח: ${esc(o.note)}</p>`:''}${openRequest(o)?`<section class="notice warn decision-request"><strong>${o.request.type==='change'?'בקשת שינוי':'בקשת ביטול'} ${o.request.status==='stock_conflict'?'— חסר מלאי, נדרשת הכרעה':'ממתינה'}</strong><p>ההזמנה המקורית בתוקף עד הכרעה בבקשה.</p>${o.request.type==='change'?diff(o):''}${admin?`<div class="row wrap"><button class="primary" data-action="resolve" data-id="${o.id}" data-approve="true">אישור ${o.request.type==='change'?'השינוי':'הביטול'}</button><button class="secondary" data-action="resolve" data-id="${o.id}" data-approve="false">דחיית הבקשה</button>${o.request.type==='change'?`<button class="text-btn" data-action="edit-order" data-id="${o.id}" data-mode="resolve">עריכת ההצעה</button>`:''}</div>`:''}</section>`:''}<div class="form-actions wrap">${admin?`${o.status==='pending_approval'?`<button class="primary" data-action="approve" data-id="${o.id}">אישור הזמנה ועסק</button><button class="secondary" data-action="edit-order" data-id="${o.id}" data-mode="approve">עריכה ואישור</button><button class="text-btn danger" data-action="reject" data-id="${o.id}">דחייה</button>`:''}${['received','picking'].includes(o.status)?`<button class="primary" data-action="advance" data-id="${o.id}" ${openRequest(o)?'disabled':''}>${o.status==='received'?'העבר לליקוט':'סמן כהושלמה'}</button>${openRequest(o)?'<button class="text-btn" data-action="focus-request">יש להכריע בבקשה לפני מעבר לליקוט ↑</button>':''}`:''}`:o.status==='received'&&!openRequest(o)?`<button class="primary" data-action="edit-order" data-id="${o.id}" data-mode="change">בקשת שינוי</button><button class="secondary" data-action="cancel" data-id="${o.id}">בקשת ביטול</button>`:o.status==='pending_approval'?'<p class="muted">הצוות בודק את ההזמנה הראשונה שלכם.</p>':['picking','completed'].includes(o.status)?'<p class="muted">לא ניתן לשנות הזמנה בשלב זה. לבירור אפשר לפנות לסוכן.</p>':''}</div><details data-details="${o.id}-timeline" style="margin-top:25px"><summary>ציר זמן ופעולות</summary><div class="timeline">${(o.events||[]).map(e=>`<div><strong>${esc(eventLabel(e.message||e.type||e.action))}</strong><br><small>${date(e.at||e.createdAt)} · ${esc(actorLabel(e.actorId||e.actor))}</small></div>`).join('')||'<div>ההזמנה נוצרה</div>'}</div></details>`}
const modules=[['inbox','לטיפול'],['orders','כל ההזמנות'],['products','מוצרים'],['inventory','מלאי'],['categories','קטגוריות'],['businesses','עסקים'],['settings','הגדרות'],['notifications','התראות']];
function admin(){let items=ownOrders();if(view==='inbox')items=items.filter(o=>o.status==='pending_approval'||openRequest(o));if(view==='orders'){items=items.filter(o=>(filter==='all'||o.status===filter)&&(!dateFrom||o.createdAt.slice(0,10)>=dateFrom)&&(!dateTo||o.createdAt.slice(0,10)<=dateTo)&&normalize(o.number+' '+o.businessSnapshot?.name+' '+o.businessSnapshot?.contactName).includes(normalize(query)))}let content='';if(['inbox','orders'].includes(view)){const o=items.find(o=>o.id===selected);content=`${view==='inbox'?`<label class="inbox-sort">סדר הטיפול<select id="inbox-sort"><option value="oldest" ${inboxSort==='oldest'?'selected':''}>הוותיקות תחילה</option><option value="newest" ${inboxSort==='newest'?'selected':''}>החדשות תחילה</option></select></label>`:''}${view==='orders'?`<div class="row order-tools" style="margin-bottom:20px"><input id="admin-search" type="search" placeholder="מספר הזמנה, עסק או איש קשר" value="${esc(query)}" aria-label="חיפוש הזמנות"><select id="order-filter" aria-label="סינון סטטוס"><option value="all">כל הסטטוסים</option>${Object.entries(statuses).map(([k,v])=>`<option value="${k}" ${filter===k?'selected':''}>${v}</option>`).join('')}</select><label class="date-field">מתאריך<input id="date-from" type="date" value="${dateFrom}"></label><label class="date-field">עד תאריך<input id="date-to" type="date" value="${dateTo}"></label><button class="text-btn" data-action="clear-search">ניקוי סינון</button></div>`:''}<div class="desk ${o?'has-selection':''}"><div class="queue" data-scroll="queue"><small>${items.length} ${view==='inbox'?'עניינים לטיפול':'הזמנות'} · הישנות ממתינות לכם</small>${(view==='inbox'?[...items].sort((a,b)=>(inboxSort==='oldest'?1:-1)*String(a.request?.createdAt||a.createdAt).localeCompare(String(b.request?.createdAt||b.createdAt))):items).map(orderButton).join('')||'<div class="empty"><h3>הכול מטופל</h3><p>בקשות חדשות יופיעו כאן.</p></div>'}</div><section class="focus-pane">${o?orderDetail(o):'<div class="empty"><div class="eyebrow">שולחן העבודה פנוי</div><h2>בוחרים עניין. רואים את התמונה.</h2><p>פרטי ההזמנה והפעולות ייפתחו כאן לצד התור.</p></div>'}</section></div><div class="operations"><button data-action="view" data-view="orders" data-filter="received">${db.orders.filter(o=>o.status==='received').length} הזמנות שהתקבלו</button><button data-action="view" data-view="inventory" data-filter="low">${db.products.filter(p=>p.stock>0&&p.stock<=3).length} מוצרים במלאי נמוך</button></div>`}else if(['products','inventory'].includes(view)){const ps=db.products.filter(p=>(filter==='all'||(filter==='active'?p.active:filter==='inactive'?!p.active:filter==='low'?p.stock>0&&p.stock<=3:p.stock===0))&&normalize(p.name+' '+p.sku).includes(normalize(query)));const p=db.products.find(p=>p.id===selected);content=`<div class="row order-tools" style="margin-bottom:20px"><input id="admin-search" type="search" value="${esc(query)}" placeholder="חיפוש מוצר או מק״ט" aria-label="חיפוש מוצר"><select id="product-filter" aria-label="מצב מוצר"><option value="all">כל המוצרים</option><option value="active" ${filter==='active'?'selected':''}>פעילים</option><option value="inactive" ${filter==='inactive'?'selected':''}>מושבתים</option><option value="low" ${filter==='low'?'selected':''}>מלאי נמוך</option><option value="out" ${filter==='out'?'selected':''}>אזלו</option></select>${view==='products'?'<button class="primary" data-action="new-product">מוצר חדש +</button>':''}</div><div class="desk ${p?'has-selection':''}"><div class="queue"><small>${ps.length} מוצרים בסינון הנוכחי</small>${ps.map(p=>`<button class="queue-item ${selected===p.id?'active':''}" data-action="select-product" data-id="${p.id}"><div class="row spread"><strong>${esc(p.name)}</strong><span class="tag">${p.active?'פעיל':'מושבת'}</span></div><small>${esc(p.sku)} · ${p.stock} ארגזים · ${money(p.price)}</small></button>`).join('')||'<p>לא נמצאו מוצרים בסינון הנוכחי.</p>'}</div><section class="focus-pane">${p?`<button class="text-btn mobile-back" data-action="back-list">חזרה →</button>${view==='products'?productForm(p):inventoryPane(p)}`:'<div class="empty"><h2>כל מוצר, בהקשר שלו</h2><p>בחרו מוצר לעריכה או לבדיקת התנועות במלאי.</p></div>'}</section></div>`}else if(view==='categories'){content=`<div class="desk"><div class="queue"><button class="primary" data-action="new-category">קטגוריה חדשה +</button>${db.categories.map(c=>`<button class="queue-item" data-action="category-edit" data-id="${c.id}"><h3>${esc(c.name)}</h3><small>${c.active?'פעילה':'מושבתת'} · ${db.products.filter(p=>p.categoryId===c.id).length} מוצרים</small></button>`).join('')}</div><section class="focus-pane"><h2>הסדר על המדף</h2><p class="muted">קטגוריות מארגנות את הקטלוג. השבתה מסתירה קטגוריה מהלקוחות ומשמרת את שיוכי המוצרים.</p><div class="notice">לא ניתן למחוק קטגוריה שמשויכים אליה מוצרים.</div></section></div>`}else if(view==='businesses'){content=`<input id="admin-search" type="search" placeholder="חיפוש עסק או איש קשר" aria-label="חיפוש עסקים" value="${esc(query)}" style="margin-bottom:20px"><div class="desk ${selected?'has-selection':''}"><div class="queue">${db.businesses.filter(b=>normalize(b.name+' '+b.contactName).includes(normalize(query))).map(b=>`<button class="queue-item" data-action="business" data-id="${b.id}"><h3>${esc(b.name)}</h3><small>${b.active?'פעיל':'מושבת'} · ${b.approved?'מאושר':'ממתין להזמנה ראשונה'}</small></button>`).join('')}</div><section class="focus-pane">${selected?businessContext(db.businesses.find(b=>b.id===selected)):'<h2>העסקים שמאחורי ההזמנות</h2><p class="muted">פרופיל, כתובת והיסטוריה נפרדים לכל עסק.</p>'}</section></div>`}else if(view==='settings'){content=`<section class="focus-pane" style="max-width:650px"><h2>כללי המסחר</h2><form id="settings-form" class="stack"><label>מינימום הזמנה לפני מע״מ, בש״ח<input name="minimumOrder" type="number" min="0" step=".01" value="${db.settings.minimumOrder/100}" required></label><label>שיעור מע״מ באחוזים<input name="vatRate" type="number" min="0" max="100" step=".01" value="${db.settings.vatRate*100}" required></label><p class="notice">שינויים חלים על פעולות חדשות; שיעור המע״מ בהזמנות קיימות נשמר.</p><button class="primary">שמירת הגדרות</button><p class="form-error field-error"></p></form></section>`}else{content=`<section class="focus-pane"><h2>יומן התראות</h2><p class="notice">${repo.mode==='demo'?'יומן הדגמה — הודעות אינן נשלחות בפועל.':'אירועים ממתינים לחיבור ספק הודעות.'}</p>${db.notifications.map(n=>`<div class="ledger-item"><strong>${esc(eventLabel(n.eventType||n.message||n.type||n.event))}</strong><div class="muted">${date(n.createdAt)} · ${esc(n.status||'ממתינה')} · ${esc(n.orderId||'')}</div></div>`).join('')||'<p class="muted">אירועים יופיעו לאחר פעולות בהזמנות.</p>'}</section>`}return `<div class="intro"><div><div class="eyebrow">שולחן התפעול</div><h1>${modules.find(m=>m[0]===view)?.[1]||'לטיפול'}</h1><p>הדברים החשובים, בתוך ההקשר שלהם.</p></div><span class="pill">${new Date().toLocaleDateString('he-IL',{weekday:'long',day:'numeric',month:'long'})}</span></div><nav class="admin-nav" aria-label="סביבת תפעול">${modules.map(([k,n])=>`<button class="${view===k?'active':''}" data-action="view" data-view="${k}">${n}</button>`).join('')}</nav>${content}`}
function productForm(p={}){return `<form id="product-form" data-id="${esc(p.id||'')}" class="stack"><div class="row spread"><h2>${p.id?'עריכת מוצר':'מוצר חדש'}</h2><small id="product-draft-status">תצוגה מקדימה</small></div><div class="product-art" id="product-preview" style="height:140px;border-radius:12px">${art({...p,id:p.id||'new'})}</div><div class="field-grid"><label>שם מוצר<input name="name" value="${esc(p.name||'')}" required></label><label>מק״ט<input name="sku" value="${esc(p.sku||'M-'+Date.now().toString().slice(-6))}" required><small id="sku-error" class="field-error"></small></label><label>מחיר ארגז לפני מע״מ, ₪<input name="price" type="number" min=".01" step=".01" value="${p.price?p.price/100:''}" required></label><label>יחידות בארגז<input name="unitsPerCase" type="number" min="1" step="1" value="${p.unitsPerCase||12}" required></label><label>קטגוריה<select name="categoryId">${db.categories.filter(c=>c.active||c.id===p.categoryId).map(c=>`<option value="${c.id}" ${p.categoryId===c.id?'selected':''}>${esc(c.name)}${!c.active?' (מושבתת)':''}</option>`).join('')}</select></label>${p.id?`<label>מלאי נוכחי<input value="${p.stock} ארגזים" readonly><button type="button" class="text-btn" data-action="adjust" data-id="${p.id}">תיקון מלאי מתועד</button></label>`:'<label>מלאי פתיחה בארגזים<input name="stock" type="number" min="0" step="1" value="0" required></label>'}<label class="full">תיאור<textarea name="description" required>${esc(p.description||'')}</textarea></label><label class="full">תמונת מוצר (עד 1MB)<input name="imageFile" type="file" ${!p.image?'required':''} accept="image/jpeg,image/png,image/webp"><small id="upload-status">התמונה תועלה בעת שמירה.</small></label><label class="check"><input name="active" type="checkbox" ${p.active!==false?'checked':''}>פעיל בקטלוג</label></div><div class="row"><button class="primary">שמירת מוצר</button><span class="form-error field-error"></span></div></form>`}
function inventoryPane(p){const events=db.inventoryEvents.filter(e=>e.productId===p.id);return `<div class="eyebrow">כרטיס מלאי · ${esc(p.sku)}</div><h2>${esc(p.name)}</h2><div class="row spread"><strong style="font-size:44px">${p.stock}<small style="font-size:14px"> ארגזים זמינים</small></strong><button class="primary" data-action="adjust" data-id="${p.id}">תיקון מלאי ±</button></div><h3 class="rule" style="margin-top:25px">תנועות אחרונות</h3><div class="ledger">${[...events].reverse().map(e=>`<div class="ledger-item"><div class="row spread"><strong>${e.delta>0?'+':''}${e.delta} ארגזים</strong><small>${date(e.createdAt||e.at)}</small></div><div>${esc(eventLabel(e.reason||e.type))} ${e.orderId?`· ${esc(e.orderId)}`:''}</div><small>${e.before??'—'} → ${e.after??'—'} · ${esc(actorLabel(e.actorId))}</small></div>`).join('')||'<p class="muted">אין תנועות להצגה.</p>'}</div>`}
function render(){const c=ctx();actor=viewActor();db=repo.snapshot();db.products.forEach(p=>productCache.set(p.id,p));if(!actor){app.innerHTML=welcome();return}app.innerHTML=header()+`<main class="page">${!actor.businessId&&actor.role!=='admin'?`<div class="intro"><div><div class="eyebrow">נעים להכיר</div><h1>העסק שלכם עולה על המדף</h1></div></div><section class="focus-pane" style="max-width:650px">${businessForm({},true)}</section>`:actor.role==='admin'?admin():view==='orders'?orderList():catalog()}</main>`+(actor.role==='customer'&&actor.businessId?living():'')+`<div class="edge right" data-edge="nav"></div><div class="edge left" data-edge="tools"></div>`;document.body.classList.toggle('cart-open',expanded&&actor.role==='customer');restore(c);app.inert=!!dialog;stampVersions();bindGestures();updateRails();if(enterView){enterView=false;$('main.page')?.classList.add('view-enter')}}
function businessForm(b,onboard=false){return `<form id="business-form" data-id="${esc(b.id||'')}" data-onboard="${onboard}" class="stack"><div class="field-grid">${[['name','שם העסק'],['taxId','ח.פ / ע.מ'],['contactName','איש קשר'],['phone','טלפון'],['address','כתובת אספקה מלאה']].map(([k,l])=>`<label class="${k==='address'?'full':''}">${l}<input name="${k}" value="${esc(b[k]||'')}" ${!onboard&&actor.role!=='admin'&&['name','taxId'].includes(k)&&ownOrders().length?'readonly':''} required ${k==='phone'?'type="tel"':''}></label>`).join('')}</div><p class="notice">פרטי העסק והכתובת נשמרים בהזמנה בזמן שליחתה. עדכון כאן ישפיע על הזמנות חדשות.</p><button class="primary">${onboard?'שמירה וכניסה למדף':'שמירת פרטים'}</button><p class="form-error field-error"></p></form>`}
function showDialog(title,body,wide=false){if(!dialog)returnFocus=document.activeElement;dialog={title,returnFocusId:returnFocus?.id};overlays.innerHTML=`<div class="overlay" data-backdrop><section class="dialog ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2><button class="icon-btn" data-action="close" aria-label="סגור">×</button></header>${body}</section></div>`;app.inert=true;setTimeout(()=>$('input,button,select,textarea',overlays)?.focus(),0);stampVersions();bindGestures()}
// Overlays leave with a short exit animation; the element is detached immediately from app state,
// so a dialog opened right after replaces it without waiting.
const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)');
function closeOverlay(){const el=overlays.firstElementChild;if(!el||reducedMotion.matches){overlays.innerHTML='';return}el.classList.add('closing');el.setAttribute('aria-hidden','true');el.removeAttribute('data-backdrop');el.querySelectorAll('[role="dialog"],[data-drawer],[id]').forEach(d=>{d.removeAttribute('role');d.removeAttribute('data-drawer');d.removeAttribute('id')});el.inert=true;setTimeout(()=>el.remove(),240)}
function closeDialog(){if(returnFocus?.matches?.('[data-action="drawer"]'))returnFocus.setAttribute('aria-expanded','false');closeOverlay();dialog=null;app.inert=false;(document.getElementById(returnFocus?.id)||(returnFocus?.isConnected?returnFocus:null)||document.getElementById('nav-toggle'))?.focus?.({preventScroll:true})}
function showDrawer(side){returnFocus=document.getElementById(side==='nav'?'nav-toggle':'tools-toggle')||document.activeElement;returnFocus?.setAttribute('aria-expanded','true');dialog={side};const nav=actor.role==='admin'?modules:[['catalog','המדף שלי'],['orders','ההזמנות שלי']];overlays.innerHTML=`<div class="overlay drawer-overlay" data-backdrop><section id="${side==='nav'?'navigation':'tools'}-drawer" class="drawer ${side==='tools'?'tools':''}" role="dialog" aria-modal="true" aria-label="${side==='nav'?'ניווט':'כלים'}" data-drawer="${side}"><div class="row spread">${logo}<button class="icon-btn" data-action="close" aria-label="סגור">×</button></div><nav>${side==='nav'?nav.map(([k,n])=>`<button data-action="view" data-view="${k}">${n}</button>`).join('')+`<button data-action="profile">פרטי העסק</button><button data-action="logout">יציאה מהחשבון</button>`:actor.role==='admin'?'<button data-action="new-product">יצירת מוצר</button><button data-action="view" data-view="inventory">תיקון מלאי</button><button data-action="view" data-view="orders">חיפוש הזמנה</button>':'<button data-action="focus-search">חיפוש מהיר</button><button data-action="open-cart">הטיוטה שלי</button><button data-action="view" data-view="orders">מעקב הזמנות</button>'}</nav><p class="muted" style="margin-top:35px">${repo.mode==='demo'?'סביבת הדגמה · מדף V2':'מדף — הזמנות לעסקים'}</p></section></div>`;app.inert=true;$('button',overlays)?.focus();bindGestures()}
async function command(cmd,form){if(busy)return false;busy=true;lastErrorCode=null;const buttons=form?$$('button',form):[];buttons.forEach(b=>b.disabled=true);try{const fingerprint=JSON.stringify(cmd);if(form&&form.dataset.commandFingerprint!==fingerprint){form.dataset.commandFingerprint=fingerprint;form.dataset.commandKey=uid()}await repo.command({key:form?.dataset.commandKey||uid(),...cmd});db=repo.snapshot();actor=viewActor();return true}catch(e){lastErrorCode=e.code||e.details?.code;const msg=e.message||'הפעולה לא הושלמה';if(form&&$('.form-error',form))$('.form-error',form).textContent=msg;else toast(msg);return false}finally{busy=false;buttons.forEach(b=>b.disabled=false)}}
function patchCart(){const c=ctx();$$('[data-product]').forEach(el=>{const p=product(el.dataset.product),q=cart[p.id]||0;el.classList.toggle('selected',q>0);$('.selected-label',el)?.classList.toggle('hidden',!q);$$('[data-quantity]',el).forEach(i=>i.value=q);$('.units',el).textContent=q?`${q} ארגזים · ${q*p.unitsPerCase} יחידות`:'ארגזים שלמים, לבחירתך'});const l=$('.living');if(l){const box=document.createElement('div');box.innerHTML=living();const fresh=box.firstElementChild;l.className=fresh.className;l.style.height='';l.style.transition='';const handle=$('.living-handle',l);handle.innerHTML=$('.living-handle',fresh).innerHTML;handle.setAttribute('aria-expanded',String(expanded));$('.living-content',l).innerHTML=$('.living-content',fresh).innerHTML;}if(dialog?.quick){const p=product(dialog.quick);$$('[data-quantity]',overlays).forEach(i=>i.value=cart[p.id]||0)}restore(c);bindGestures()}
function setQuantity(id,value){if(pendingSubmit){toast('תוצאת השליחה טרם אומתה. פתחו את האישור ובדקו את אותה שליחה לפני שינוי הטיוטה.');return}const p=product(id);if(!p)return;let q=Number(value);if(!Number.isInteger(q)||q<0){toast('יש להזין מספר שלם של ארגזים');patchCart();return}if(q>p.stock||!p.active){toast(`ביקשת ${q} ארגזים; זמינים ${p.active?p.stock:0}`,{label:'עדכן לכמות הזמינה',run:()=>setQuantity(id,p.active?p.stock:0)});patchCart();return}if(q)cart[id]=q;else delete cart[id];saveDraft();patchCart()}
function quick(id){const p=product(id);showDialog(p.name,`<div class="product-art">${art(p)}</div><small>${esc(p.sku)} · ${p.unitsPerCase} יחידות בארגז</small><p style="margin-top:15px">${esc(p.description||'נבחר בקפידה למדף שלכם.')}</p><div class="row spread"><strong class="price">${money(p.price)} <small>לפני מע״מ</small></strong>${quantity(p,cart[id]||0,'quick')}</div><p class="stock">${p.stock<=3?`נותרו ${p.stock} ארגזים`:'זמין להזמנה'}</p>`);dialog.quick=id}
function checkout(){if(!cartItems().length)return;showDialog('בדיקה אחרונה, וההזמנה בדרך',`<div class="notice"><strong>${esc(biz()?.name)}</strong><p>${esc(biz()?.address)}</p><button class="text-btn" data-action="checkout-profile">עדכון כתובת</button></div>${lines(cartItems().map(({p,q})=>({...p,productId:p.id,quantity:q})))}${totals(subtotal())}<p>${esc(note)}</p><p class="muted">${biz()?.approved?'ההזמנה תתקבל לאחר אישור השליחה.':'ההזמנה הראשונה תועבר לאישור הצוות.'}</p><form id="checkout-form"><button class="primary" style="width:100%" ${!navigator.onLine&&repo.mode!=='demo'?'disabled':''}>שליחת הזמנה</button><p class="form-error field-error" role="alert"></p></form>`);dialog.expectedPrices=Object.fromEntries(cartItems().map(({p})=>[p.id,p.price]));}
let editItems={};
function editOrder(id,mode){const o=db.orders.find(o=>o.id===id);editItems=Object.fromEntries((mode==='resolve'?o.request.items:o.items).map(i=>[i.productId,i.quantity]));const list=[...db.products.filter(p=>p.active||o.items.some(i=>i.productId===p.id)),...o.items.filter(i=>!db.products.some(p=>p.id===i.productId)).map(i=>({...i,id:i.productId,active:false,stock:0}))];showDialog(mode==='approve'?'עריכת הזמנה ראשונה ואישור':'עריכת הצעת שינוי',`<p class="notice">מחיר פריט קיים נשמר. פריט חדש מקבל את המחיר הנוכחי. מינימום ${money(db.settings.minimumOrder)} לפני מע״מ.</p><form id="edit-order-form" data-id="${id}" data-version="${o.version}" data-mode="${mode}">${list.map(p=>`<div class="cartline"><div><strong>${esc(p.name)}</strong><br><small>${!p.active?'מושבת — ניתן לשמר או להפחית':`${p.stock} זמינים לתוספת`}</small></div>${quantity(p,editItems[p.id]||0,'edit')}</div>`).join('')}<div class="form-actions"><button class="primary">${mode==='change'?'שליחת בקשת שינוי':'אישור ההצעה'}</button></div><p class="form-error field-error"></p></form>`,true)}
function confirmAction(title,body,run){showDialog(title,`<p>${body}</p><div class="form-actions"><button class="primary" id="confirm-action">אישור</button><button class="secondary" data-action="close">חזרה</button></div><p class="form-error field-error"></p>`);$('#confirm-action').onclick=async()=>{if(await run()) {closeDialog();render();toast('הפעולה נשמרה')}}}
const workspaces={};let editDrafts={},pendingSubmit=null,refreshPending=false;
let enterView=false;
function navigate(next){enterView=true;workspaces[view]={query,filter,selected,category,scroll:ctx().scroll,details:ctx().details,top:scrollY};view=next;const w=workspaces[next]||{};query=w.query||'';filter=w.filter||'all';selected=w.selected||null;category=w.category||'all';closeDialog();render();if(w.scroll)restore({scroll:w.scroll,details:w.details});scrollTo(0,w.top||0)}
function categoryEditor(c={}){showDialog(c.id?'עריכת קטגוריה':'קטגוריה חדשה',`<form id="category-form" data-id="${esc(c.id||'')}" class="stack"><label>שם הקטגוריה<input name="name" required value="${esc(c.name||'')}"></label><label>סדר המדף<input name="sortOrder" type="number" step="1" value="${c.sortOrder??db.categories.length+1}" required></label><label class="check"><input type="checkbox" name="active" ${c.active!==false?'checked':''}>קטגוריה פעילה</label><div class="row"><button class="primary">שמירה</button>${c.id?`<button type="button" class="text-btn danger" data-action="delete-category" data-id="${esc(c.id)}" ${db.products.some(p=>p.categoryId===c.id)?'disabled':''}>מחיקה</button>`:''}</div><p class="form-error field-error"></p></form>`)}
function adjustment(id){const p=product(id);showDialog('תיקון מלאי · '+p.name,`<form id="inventory-form" data-id="${id}" class="stack"><div class="notice">מלאי נוכחי: <strong>${p.stock} ארגזים</strong></div><label>שינוי בכמות — תוספת או הפחתה<input name="delta" type="number" step="1" required placeholder="לדוגמה 3 או ‎-2"></label><label>סיבת השינוי<input name="reason" required maxlength="500" placeholder="ספירה, נזק או קבלת מלאי"></label><div id="stock-preview" class="notice">הזינו שינוי כדי לראות יתרה צפויה.</div><button class="primary">שמירת תיקון מתועד</button><p class="form-error field-error"></p></form>`)}
function showBusiness(id){const b=db.businesses.find(b=>b.id===id);showDialog(b.name,`${businessForm(b)}${actor.role==='admin'?`<div class="rule"><p>${b.approved?'עסק מאושר':'אישור יתבצע דרך הזמנה ראשונה'} · ${db.orders.filter(o=>o.businessId===id).length} הזמנות</p><button class="secondary" data-action="business-active" data-id="${id}" data-active="${!b.active}">${b.active?'השבתת עסק':'הפעלת עסק'}</button><h3 style="margin-top:20px">היסטוריית העסק</h3>${db.orders.filter(o=>o.businessId===id).map(orderButton).join('')}<h3 style="margin-top:20px">משתמשים</h3>${db.users.filter(u=>u.businessId===id).map(u=>`<p>${esc(u.name||u.id)}</p>`).join('')}<details><summary>שינויי פרופיל</summary>${(db.auditEvents||[]).filter(e=>e.businessId===id).map(e=>`<p>${esc(eventLabel(e.type))} · ${date(e.at)} · ${esc(e.actorId)}</p>`).join('')}</details></div>`:''}`,true)}
function actionOrder(id){return db.orders.find(o=>o.id===id)}
function stampVersions(){ $$('[data-id]').forEach(el=>{if(['approve','reject','advance','resolve','cancel'].includes(el.dataset.action)){const o=db.orders.find(o=>o.id===el.dataset.id);if(o&&!el.dataset.version)el.dataset.version=o.version}})}
function actorLabel(id){return db.users.find(u=>u.id===id)?.name||(id==='admin'?'צוות מדף':'משתמש עסקי')}
function bindGestures(){/* Gesture listeners are delegated once below. */}
document.addEventListener('click',async e=>{
 const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;
 if(performance.now()<suppressUntil){e.preventDefault();return}
 if(a==='login'){try{await repo.signIn(b.dataset.persona,$('#demo-business')?.value);actor=viewActor();view=actor.role==='admin'?'inbox':'catalog';cart={};note='';selected=null;query='';filter='all';loadDraft();render()}catch(err){toast(err.message)}}
 else if(a==='mode'){mode=mode==='admin'?'customer':'admin';try{localStorage.setItem(MODE_KEY,mode)}catch{};actor=viewActor();view=actor.role==='admin'?'inbox':'catalog';selected=null;query='';filter='all';expanded=false;closeDialog();loadDraft();render();toast(mode==='admin'?'מצב ניהול':'מצב לקוח')}
 else if(a==='logout'){await repo.signOut();if(repo.mode==='firebase'){location.assign('/');return}cart={};note='';expanded=false;closeDialog();render()}
 else if(a==='view'){navigate(b.dataset.view);if(b.dataset.filter){filter=b.dataset.filter;dateFrom=b.dataset.from||'';render()}}
 else if(a==='category'){category=id;render()}
 else if(a==='clear-search'){query='';category='all';filter='all';dateFrom='';dateTo='';render()}
 else if(a==='rail'){$(`[data-scroll="${id}"]`)?.scrollBy({left:b.dataset.dir==='prev'?350:-350,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}
 else if(a==='quick')quick(id);
 else if(a==='qty'){const prefix=b.dataset.prefix;if(prefix==='edit'){editItems[id]=Math.max(0,(editItems[id]||0)+Number(b.dataset.delta));$(`[data-quantity="${id}"][data-prefix="edit"]`).value=editItems[id]}else setQuantity(id,(cart[id]||0)+Number(b.dataset.delta))}
 else if(a==='expand'){expanded=!expanded;patchCart();document.body.classList.toggle('cart-open',expanded)}
 else if(a==='open-cart'){closeDialog();expanded=true;patchCart();document.body.classList.add('cart-open')}
 else if(a==='remove'&&pendingSubmit)toast('יש לבדוק את תוצאת השליחה לפני שינוי הטיוטה');
 else if(a==='remove'){undo={id,q:cart[id]};delete cart[id];saveDraft();patchCart();toast('המוצר הוסר',{label:'החזרה',run:()=>{if(undo)setQuantity(undo.id,undo.q);undo=null}})}
 else if(a==='checkout')checkout();
 else if(a==='close')closeDialog();
 else if(a==='drawer')showDrawer(b.dataset.side);
 else if(a==='order'){selected=id;if(actor.role==='admin'){closeDialog();if(!['inbox','orders'].includes(view))view='orders';render()}else showDialog('פרטי הזמנה',orderDetail(actionOrder(id)),true)}
 else if(a==='back-list'){selected=null;render()}
 else if(a==='copy'){try{await navigator.clipboard.writeText(b.dataset.value);toast('מספר ההזמנה הועתק')}catch{toast('מספר ההזמנה: '+b.dataset.value)}}
 else if(a==='copy-link'){try{const link=new URL(location.href);link.hash='order='+encodeURIComponent(id);await navigator.clipboard.writeText(link.href);toast('הקישור הועתק — הגישה כפופה להתחברות')}catch{toast('לא ניתן להעתיק קישור בדפדפן הזה')}}
 else if(a==='edit-order')editOrder(id,b.dataset.mode);
 else if(a==='cancel'){const o=actionOrder(id);confirmAction('בקשת ביטול',`לבקש לבטל את הזמנה ${esc(o.number)}? המלאי יוחזר רק לאחר אישור המנהל.`,()=>command({type:'requestCancel',orderId:id,version:Number(b.dataset.version||o.version)}))}
 else if(a==='approve'){const o=actionOrder(id);if(await command({type:'approveOrder',orderId:id,version:Number(b.dataset.version||o.version)})){await settleOrder(id);render();toast('ההזמנה אושרה והעסק יכול להזמין ישירות')}}
 else if(a==='reject'){const o=actionOrder(id);confirmAction('דחיית הזמנה',`הזמנה ${esc(o.number)} של ${esc(o.businessSnapshot.name)} תידחה. ${o.items.reduce((n,i)=>n+i.quantity,0)} ארגזים יוחזרו למלאי.`,()=>command({type:'rejectOrder',orderId:id,version:Number(b.dataset.version||o.version)}))}
 else if(a==='advance'){const o=actionOrder(id);if(await command({type:'advanceOrder',orderId:id,version:Number(b.dataset.version||o.version)})){render();toast('סטטוס ההזמנה עודכן')}}
 else if(a==='resolve'){const o=actionOrder(id),approve=b.dataset.approve==='true';const run=()=>command({type:'resolveRequest',orderId:id,version:Number(b.dataset.version||o.version),approve});if(approve&&o.request.type==='cancel')confirmAction('אישור ביטול',`הזמנה ${esc(o.number)} תבוטל ו־${o.items.reduce((n,i)=>n+i.quantity,0)} ארגזים יוחזרו למלאי.`,run);else if(await run()){await settleOrder(id);render();toast(actionOrder(id).request?.status==='stock_conflict'?'חסר מלאי — הבקשה נשארה פתוחה לטיפול':'ההחלטה נשמרה')}}
 else if(a==='new-product'){closeDialog();showDialog('מוצר חדש',productForm(),true);restoreProductDraft('new')}
 else if(a==='select-product'){selected=id;render();restoreProductDraft(id)}
 else if(a==='adjust')adjustment(id);
 else if(a==='new-category')categoryEditor();
 else if(a==='category-edit')categoryEditor(db.categories.find(c=>c.id===id));
 else if(a==='delete-category'){if(await command({type:'deleteCategory',categoryId:id})){closeDialog();render();toast('הקטגוריה נמחקה')}}
 else if(a==='business'){selected=id;view='businesses';render()}
 else if(a==='business-active'){const active=b.dataset.active==='true';confirmAction(active?'הפעלת עסק':'השבתת עסק',active?'העסק יוכל לשלוח הזמנות חדשות.':'הזמנות קיימות וההיסטוריה יישמרו; שליחת הזמנות חדשות תיחסם.',()=>command({type:'setBusinessActive',businessId:id,active}))}
 else if(a==='profile'){if(actor.role==='admin')navigate('businesses');else if(biz())showBusiness(biz().id)}
 else if(a==='checkout-profile'){showBusiness(biz().id);dialog.returnCheckout=true}
 else if(a==='focus-search'){navigate('catalog');$('#search')?.focus()}
 else if(a==='load-draft'){draftConflict=null;loadDraft();render()}
 else if(a==='focus-request')$('.decision-request')?.scrollIntoView({behavior:'smooth',block:'center'});
 else if(a==='refresh'){refreshPending=false;render();toast('הנתונים עודכנו')}
 else if(a==='discard-product-draft'){const f=b.closest('form'),key=f.dataset.id||'new';delete editDrafts[key];try{sessionStorage.setItem(editDraftKey(),JSON.stringify(editDrafts))}catch{};f.reset();toast('הטיוטה נמחקה')}
 else if(a==='clear-cart'&&pendingSubmit)toast('יש לבדוק את תוצאת השליחה לפני מחיקת הטיוטה');
 else if(a==='clear-cart')confirmAction('מחיקת טיוטה','הפריטים וההערה יוסרו מהטיוטה בלבד. ההזמנות שנשלחו יישמרו.',async()=>{cart={};note='';saveDraft();return true});
});
document.addEventListener('click',e=>{if(e.target.matches('[data-backdrop]'))closeDialog()});
document.addEventListener('focusin',e=>{if(e.target.matches('[data-quantity]'))e.target.select()});
document.addEventListener('change',e=>{const t=e.target;if(t.matches('[data-quantity]')){if(t.dataset.prefix==='edit'){const n=Number(t.value);if(!Number.isInteger(n)||n<0){t.value=editItems[t.dataset.quantity]||0;toast('נדרשת כמות שלמה ולא שלילית')}else editItems[t.dataset.quantity]=n}else setQuantity(t.dataset.quantity,t.value===''?cart[t.dataset.quantity]||0:t.value)}if(t.id==='inbox-sort'){inboxSort=t.value;render()}if(t.id==='order-filter'||t.id==='product-filter'){filter=t.value;selected=null;render()}if(t.id==='date-from'||t.id==='date-to'){if(t.id==='date-from')dateFrom=t.value;else dateTo=t.value;render()}if(t.matches('[name="imageFile"]'))previewImage(t)});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='search'||t.id==='admin-search'){query=t.value;render()}if(t.id==='cart-note'){if(pendingSubmit){t.value=note;toast('יש לבדוק את השליחה הממתינה לפני עריכת ההערה')}else{note=t.value;saveDraft()}}if(t.closest('#inventory-form')&&t.name==='delta'){const p=product(t.closest('form').dataset.id),v=Number(t.value);$('#stock-preview').textContent=`${p.stock} במלאי ${v>=0?'+':'−'} ${Math.abs(v)} = ${p.stock+v} ארגזים`;$('#stock-preview').classList.toggle('warn',p.stock+v<0)}if(t.closest('#product-form')){const f=t.closest('form');captureProductDraft(f);const sku=f.elements.sku.value;$('#sku-error').textContent=db.products.some(p=>p.id!==f.dataset.id&&normalize(p.sku)===normalize(sku))?'המק״ט כבר משויך למוצר אחר':'';updateProductPreview(f)}});
const editDraftKey=()=>`madaf-edit-drafts-${actor?.id}`;
function captureProductDraft(f){const key=f.dataset.id||'new';const data=Object.fromEntries(new FormData(f));data.needsImage=!!f.elements.imageFile.files[0];delete data.imageFile;editDrafts[key]=data;try{sessionStorage.setItem(editDraftKey(),JSON.stringify(editDrafts))}catch{};$('#product-draft-status',f).textContent='טיוטה — טרם נשמרה';}
function restoreProductDraft(key){try{editDrafts=JSON.parse(sessionStorage.getItem(editDraftKey())||'{}')}catch{}const d=editDrafts[key],f=$('#product-form');if(d&&f){for(const[k,v]of Object.entries(d)){const el=f.elements[k];if(el)el.type==='checkbox'?el.checked=v==='on':el.value=v}$('#product-draft-status',f).textContent='טיוטת העריכה שוחזרה';if(d.needsImage)$('#upload-status',f).textContent='התמונה שנבחרה לא הועלתה — יש לבחור אותה מחדש';updateProductPreview(f)}}
function updateProductPreview(f){let c=$('#product-preview-caption',f);if(!c){c=document.createElement('div');c.id='product-preview-caption';$('#product-preview',f).after(c)}c.innerHTML=`<strong>${esc(f.elements.name.value||'שם המוצר')}</strong> · ${money(Math.round(Number(f.elements.price.value)*100))} <small>לארגז · תצוגה מקדימה</small>`}
function previewImage(input){const file=input.files[0];if(!file)return;const status=$('#upload-status',input.closest('form'));if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>1048576){status.textContent='בחרו PNG, JPEG או WebP עד 1MB';input.value='';return}const old=input.dataset.preview;if(old)URL.revokeObjectURL(old);const url=URL.createObjectURL(file);input.dataset.preview=url;$('#product-preview',input.closest('form')).innerHTML=`<img src="${url}" alt="תצוגה מקדימה">`;status.textContent='תמונה נבחרה — טרם הועלתה';}
document.addEventListener('submit',async e=>{const f=e.target;if(!f.matches('form'))return;e.preventDefault();if(busy)return;const data=Object.fromEntries(new FormData(f));
 if(f.id==='business-form'){const back=dialog?.returnCheckout;const cmd=f.dataset.onboard==='true'?{type:'onboard',business:data}:{type:'updateBusiness',businessId:f.dataset.id,patch:data};if(await command(cmd,f)){closeDialog();loadDraft();render();if(back)checkout();toast('פרטי העסק נשמרו')}}
 if(f.id==='settings-form'&&await command({type:'saveSettings',settings:{minimumOrder:Math.round(Number(data.minimumOrder)*100),vatRate:Number(data.vatRate)/100}},f)){toast('ההגדרות נשמרו');render()}
 if(f.id==='category-form'&&await command({type:'saveCategory',category:{...(f.dataset.id?{id:f.dataset.id}:{}),name:data.name,sortOrder:Number(data.sortOrder),active:data.active==='on'}},f)){closeDialog();render();toast('הקטגוריה נשמרה')}
 if(f.id==='inventory-form'&&await command({type:'adjustInventory',productId:f.dataset.id,delta:Number(data.delta),reason:data.reason},f)){closeDialog();render();toast('המלאי עודכן ונשמר תיעוד')}
 if(f.id==='product-form'){const p=product(f.dataset.id),file=f.elements.imageFile.files[0];let image=p?.image||'';try{if(file){busy=true;$('#upload-status',f).textContent='מעלה תמונה…';image=await repo.uploadImage(file,percent=>{$('#upload-status',f).textContent='מעלה תמונה… '+percent+'%'});$('#upload-status',f).textContent='התמונה הועלתה';busy=false}const value={...(p?{id:p.id}:{}),name:data.name,sku:data.sku,description:data.description,categoryId:data.categoryId,price:Math.round(Number(data.price)*100),unitsPerCase:Number(data.unitsPerCase),active:data.active==='on',image,...(!p?{stock:Number(data.stock)}:{})};if(await command({type:'saveProduct',product:value},f)){delete editDrafts[f.dataset.id||'new'];try{sessionStorage.setItem(editDraftKey(),JSON.stringify(editDrafts))}catch{}closeDialog();render();toast('המוצר נשמר')}}catch(err){busy=false;$('.form-error',f).textContent=err.message}}
 if(f.id==='edit-order-form'){const items=Object.entries(editItems).filter(([,q])=>q>0).map(([productId,quantity])=>({productId,quantity}));const type=f.dataset.mode==='change'?'requestChange':f.dataset.mode==='approve'?'approveOrder':'resolveRequest';if(await command({type,orderId:f.dataset.id,version:Number(f.dataset.version),items,...(type==='resolveRequest'?{approve:true}:{})},f)){closeDialog();render();toast('ההצעה נשמרה')}}
 if(f.id==='checkout-form'){const button=$('button',f);button.textContent='שולח הזמנה…';const cmd=pendingSubmit||{type:'submitOrder',key:uid(),items:cartItems().map(({p,q})=>({productId:p.id,quantity:q})),expectedPrices:dialog.expectedPrices,note};pendingSubmit=cmd;saveDraft();const success=await command(cmd,f);if(success){pendingSubmit=null;cart={};note='';saveDraft();expanded=false;closeDialog();view='orders';render();const o=ownOrders()[0];toast('הזמנה '+o.number+' נקלטה בהצלחה')}else{button.textContent='בדיקה וניסיון חוזר';if(!lastErrorCode) $('.form-error',f).textContent+=' הטיוטה נשמרה. ניסיון חוזר יבדוק את אותה שליחה.';if(lastErrorCode&&['PRICE_CHANGED','STOCK_CONFLICT','MINIMUM_ORDER','PRODUCT_INACTIVE'].includes(lastErrorCode)){pendingSubmit=null;saveDraft();if(lastErrorCode==='PRICE_CHANGED'){const old=dialog.expectedPrices;$('.form-error',f).innerHTML=cartItems().filter(({p})=>old[p.id]!==p.price).map(({p,q})=>esc(p.name)+': '+money(old[p.id])+' ← '+money(p.price)+' (הפרש '+money((p.price-old[p.id])*q)+')').join('<br>')+'<br>המחירים השתנו. <button type="button" class="text-btn" data-action="checkout">הצג סיכום מעודכן לאישור</button>';button.disabled=true}}}}
});
let inboxSort='oldest',dateFrom='',dateTo='',lastErrorCode=null,suppressUntil=0,gesture=null;
const eventNames={order_created:'ההזמנה נשלחה',order_approved:'ההזמנה אושרה',order_rejected:'ההזמנה נדחתה',order_picking:'הועברה לליקוט',order_completed:'ההזמנה הושלמה',change_requested:'הוגשה בקשת שינוי',change_approved:'השינוי אושר',change_rejected:'בקשת השינוי נדחתה',change_stock_conflict:'חוסר מלאי בהצעת השינוי',cancel_requested:'הוגשה בקשת ביטול',cancel_approved:'הביטול אושר',cancel_rejected:'בקשת הביטול נדחתה',business_updated:'פרטי העסק עודכנו',business_created:'העסק נוצר',opening_stock:'מלאי פתיחה',order_submitted:'גריעת מלאי להזמנה',order_cancelled:'החזרת מלאי בעקבות ביטול',admin_initial_edit:'עריכת הזמנה ראשונה'};
function eventLabel(type){return eventNames[type]||type||'אירוע מערכת'}
document.addEventListener('keydown',e=>{if(!dialog)return;if(e.key==='Escape'){e.preventDefault();closeDialog();return}if(e.key==='Tab'){const els=$$('button:not(:disabled),input:not(:disabled),textarea,select,a[href],[tabindex="0"]',overlays).filter(x=>x.offsetParent!==null);if(!els.length)return;const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
const clamp=(x,a=0,b=1)=>Math.min(b,Math.max(a,x));
document.addEventListener('pointerdown',e=>{suppressUntil=0;if(e.button!==0)return;const edge=e.target.closest('[data-edge]'),handle=e.target.closest('.living-handle'),drawer=e.target.closest('[data-drawer]'),quickHead=e.target.closest('.dialog-head');if(!edge&&!handle&&!drawer&&!(quickHead&&dialog?.quick))return;if(drawer&&e.target.closest('input,textarea,select'))return;gesture={id:e.pointerId,x:e.clientX,y:e.clientY,lx:e.clientX,ly:e.clientY,t:performance.now(),vx:0,vy:0,type:edge||drawer?'drawer':handle?'living':'quick',side:edge?.dataset.edge||drawer?.dataset.drawer,startOpen:edge?false:drawer?true:expanded,target:edge||handle||drawer||quickHead,moved:false};e.target.setPointerCapture?.(e.pointerId)});
document.addEventListener('pointermove',e=>{if(!gesture||e.pointerId!==gesture.id)return;const g=gesture,dx=e.clientX-g.x,dy=e.clientY-g.y,now=performance.now(),dt=Math.max(1,now-g.t);g.vx=(e.clientX-g.lx)/dt;g.vy=(e.clientY-g.ly)/dt;g.lx=e.clientX;g.ly=e.clientY;g.t=now;if(!g.moved&&Math.hypot(dx,dy)<8)return;
 if(g.type==='drawer'){if(!g.moved&&Math.abs(dy)>Math.abs(dx)){cancelGesture();return}if(!g.moved&&!g.startOpen){showDrawer(g.side);g.el=$('[data-drawer]');}g.moved=true;g.el||=$('[data-drawer]');g.el.style.animation='none';$('.overlay',overlays)?.style.setProperty('animation','none');const width=g.el.getBoundingClientRect().width,delta=(g.side==='nav'?-dx:dx)/width,raw=(g.startOpen?1:0)+delta,p=clamp(raw);g.progress=p;g.el.style.transition='none';g.el.style.transform=`translateX(${(g.side==='nav'?1:-1)*(1-p)*width+(raw-p)*width*.12}px)`;e.preventDefault()}
 else if(g.type==='living'){if(!g.moved&&Math.abs(dx)>Math.abs(dy)){cancelGesture();return}g.moved=true;g.el=$('.living');const max=Math.min(innerHeight*.76,680),raw=(g.startOpen?1:0)-dy/(max-88);g.progress=clamp(raw);if(!$('.living-content').children.length)$('.living-content').innerHTML=cartContent();g.el.style.transition='none';g.el.style.height=`${88+(max-88)*g.progress+(raw-g.progress)*24}px`;e.preventDefault()}
 else{g.moved=true;g.el=$('.dialog');g.el.style.transition='none';g.el.style.transform=`translateY(${Math.max(0,dy)}px)`;g.progress=dy;e.preventDefault()}
},{passive:false});
function cancelGesture(){if(!gesture)return;const g=gesture;gesture=null;if(g.type==='drawer'){if(!g.startOpen)closeDialog();else if(g.el){g.el.style.transition='';g.el.style.transform=''}}else if(g.type==='living')patchCart();else if(g.el)g.el.style.transform=''}
document.addEventListener('pointercancel',cancelGesture);
document.addEventListener('pointerup',e=>{if(!gesture||e.pointerId!==gesture.id)return;const g=gesture;gesture=null;if(!g.moved)return;suppressUntil=performance.now()+400;const fresh=performance.now()-g.t<100;if(g.type==='drawer'){const velocity=fresh?(g.side==='nav'?-g.vx:g.vx):0;const open=Math.abs(velocity)>.35?velocity>0:g.progress>.5;if(!open)closeDialog();else{g.el.style.transition='';g.el.style.transform=''}}else if(g.type==='living'){expanded=fresh&&Math.abs(g.vy)>.35?g.vy<0:g.progress>.45;patchCart();document.body.classList.toggle('cart-open',expanded)}else{if(g.progress>80||(fresh&&g.vy>.5))closeDialog();else g.el.style.transform=''}});
addEventListener('storage',e=>{if(actor&&e.key===draftKey()&&e.newValue){draftConflict=true;render()}});
addEventListener('online',()=>{render();toast('החיבור חזר')});addEventListener('offline',()=>render());
repo.subscribe(()=>{db=repo.snapshot();actor=viewActor();if(busy)return;if(!actor){render();return}if(actor.role==='admin'){refreshPending=true;toast('נתונים חדשים התקבלו',{label:'רענון התצוגה',run:()=>{refreshPending=false;render()}})}else{render()}});
loadDraft();render();
if(repo.notice)toast(repo.notice);
if(location.hash.startsWith('#order=')){const id=decodeURIComponent(location.hash.slice(7));if(actor&&actionOrder(id)){selected=id;if(actor.role==='admin'){view='orders';render()}else showDialog('פרטי הזמנה',orderDetail(actionOrder(id)),true)}}

function updateRails(){for(const rail of $$('.rail')){const max=rail.scrollWidth-rail.clientWidth;for(const btn of $$('[data-action="rail"]'))if(btn.dataset.id===rail.dataset.scroll){btn.hidden=max<2;btn.disabled=btn.dataset.dir==='prev'?Math.abs(rail.scrollLeft)<2:Math.abs(rail.scrollLeft)>=max-2}}}
document.addEventListener('scroll',e=>{if(e.target.classList?.contains('rail'))updateRails()},true);addEventListener('resize',updateRails);

function waitLabel(at){const minutes=Math.max(0,Math.floor((Date.now()-new Date(at))/60000));return minutes<1?'פחות מדקה':minutes<60?minutes+' דקות':minutes<1440?Math.floor(minutes/60)+' שעות':Math.floor(minutes/1440)+' ימים'}
function businessContext(b){if(!b)return '';return `<button class="text-btn mobile-back" data-action="back-list">חזרה לרשימה →</button><h2>${esc(b.name)}</h2><div class="notice">${b.approved?'עסק מאושר':'אישור יתבצע דרך הזמנה ראשונה'} · ${b.active?'פעיל':'מושבת'}</div>${businessForm(b)}<button class="secondary" data-action="business-active" data-id="${b.id}" data-active="${!b.active}">${b.active?'השבתת עסק':'הפעלת עסק'}</button><h3 style="margin-top:25px">משתמשים משויכים</h3>${db.users.filter(u=>u.businessId===b.id).map(u=>`<p>${esc(u.name||u.id)}</p>`).join('')}<h3>הזמנות העסק</h3>${db.orders.filter(o=>o.businessId===b.id).map(orderButton).join('')}<details data-details="business-${b.id}"><summary>שינויי פרופיל</summary>${(db.auditEvents||[]).filter(e=>e.businessId===b.id).map(e=>`<p>${esc(eventLabel(e.type))} · ${date(e.at)} · ${esc(actorLabel(e.actorId))}</p>`).join('')}</details>`}

async function settleOrder(id){const el=$('.queue [data-id="'+id+'"]');if(el&&!openRequest(actionOrder(id))){el.classList.add('resolved');if(!matchMedia('(prefers-reduced-motion: reduce)').matches)await new Promise(r=>setTimeout(r,160))}}
